ALIASES = {
    'usa':'United States','us':'United States','u.s.':'United States','u.s.a.':'United States','united states of america':'United States',
    'uk':'United Kingdom','u.k.':'United Kingdom','great britain':'United Kingdom','britain':'United Kingdom',
    'uae':'United Arab Emirates','republic of korea':'South Korea','korea':'South Korea','viet nam':'Vietnam','czech republic':'Czechia',
    'global':'Worldwide','worldwide':'Worldwide','anywhere':'Worldwide','remote worldwide':'Worldwide',
}

def project(lon: float, lat: float) -> tuple[float, float]:
    width, height = WORLD_MAP_VIEWBOX
    x = (float(lon) + 180.0) / 360.0 * width
    y = (90.0 - float(lat)) / 180.0 * height
    return round(x, 1), round(y, 1)

def location_point(label: object) -> dict:
    raw = str(label or '').strip()
    if not raw:
        return {}
    canonical = ALIASES.get(raw.casefold(), raw)
    coords = COUNTRY_POINTS.get(canonical)
    if not coords:
        for name, value in COUNTRY_POINTS.items():
            if name.casefold() == canonical.casefold():
                canonical = name
                coords = value
                break
    if not coords:
        return {}
    x, y = project(coords[0], coords[1])
    return {'label': canonical, 'lon': coords[0], 'lat': coords[1], 'x': x, 'y': y}
